INSERT INTO firs (id, fir_number, title, description, acts_sections, date, police_station, location_id, investigation_id, created_at) VALUES ('fir-102', 'FIR-102/2026', 'Organized Extortion & Criminal Intimidation of Freight Transporters', 'Complaint filed by Northern Freight Carriers alleging coordinated extortion demands, physical intercept of cargo trailers at Dhaula Kuan intersection, and forced protection levy collections transferred to shell account B-008. Vehicle DL-01-AX-9921 observed performing reconnaissance.', 'IPC 384, 386, 506, 120B / BNS 308, 351, 61', '2026-08-06T00:00:00+00:00', 'Dhaula Kuan Police Station, New Delhi', 'loc-l-005', 'inv-001', '2026-08-06T00:00:00+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO firs (id, fir_number, title, description, acts_sections, date, police_station, location_id, investigation_id, created_at) VALUES ('fir-108', 'FIR-108/2026', 'Highway Cargo Hijack & Fleet Coercion at GT Road Toll', 'Commercial freight container intercepted and rerouted under coercion. Call records indicate commands originated from coordination cell linked to Suresh Nair (P-011) and Devendra Yadav (P-009).', 'IPC 392, 395, 34 / BNS 310, 3(5)', '2026-08-13T00:00:00+00:00', 'Ambala Highway Police Post', 'loc-l-015', 'inv-001', '2026-08-13T00:00:00+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO firs (id, fir_number, title, description, acts_sections, date, police_station, location_id, investigation_id, created_at) VALUES ('fir-145', 'FIR-145/2026', 'Illicit Maritime Container Tampering & Unmanifested Cargo Diversion', 'Customs enforcement raid at Nhava Sheva Terminal discovered tampered electronic seals on two 40ft refrigerated containers leased to Trident Logistics (O-001). Security footage confirms Tariq Ahmed (P-021) and Arjun Kadam (P-024) present at warehouse L-012 during midnight transfer.', 'Customs Act 1962 Sec 132, 135; IPC 420, 120B', '2026-08-19T00:00:00+00:00', 'Nhava Sheva Marine Police Station', 'loc-l-012', 'inv-001', '2026-08-19T00:00:00+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO firs (id, fir_number, title, description, acts_sections, date, police_station, location_id, investigation_id, created_at) VALUES ('fir-152', 'FIR-152/2026', 'Inter-State Contraband Transit Intercept at Mayapuri Depot', 'Raid on scrap yard L-007 recovered unmanifested industrial electronics and high-value narcotics pre-cursors transferred via container trailer MH-04-ER-4420 from Nhava Port.', 'NDPS Act Sec 21, 29; IPC 120B', '2026-08-23T00:00:00+00:00', 'Mayapuri Police Station, West Delhi', 'loc-l-007', 'inv-001', '2026-08-23T00:00:00+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO firs (id, fir_number, title, description, acts_sections, date, police_station, location_id, investigation_id, created_at) VALUES ('fir-201', 'FIR-201/2026', 'High-Volume Micro-Lending Cyber Extortion & Phishing Syndicate', 'Multi-victim cyber complaint against unauthorized loan apps harvesting contacts and threatening female victims. Ransom remittances routed through dummy UPI handles directly to mule accounts B-033 and B-021 (Swift Horizons).', 'IT Act Sec 66C, 66D; IPC 384, 509, 120B', '2026-08-09T00:00:00+00:00', 'Special Cell Cyber Crime PS, Mandir Marg', 'loc-l-014', 'inv-001', '2026-08-09T00:00:00+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO firs (id, fir_number, title, description, acts_sections, date, police_station, location_id, investigation_id, created_at) VALUES ('fir-219', 'FIR-219/2026', 'Cross-Border Hawala Settlement via Bullion Market Intermediaries', 'Financial Intelligence alert regarding structured cash withdrawals and immediate conversion to unbilled gold bullion across Chandni Chowk and Surat nodes. Linked directly to Aman Singhania (P-037) and Kunal Verma (P-033).', 'PMLA 2002 Sec 3, 4; IPC 420, 120B', '2026-08-28T00:00:00+00:00', 'Economic Offences Wing (EOW), New Delhi', 'loc-l-009', 'inv-001', '2026-08-28T00:00:00+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO firs (id, fir_number, title, description, acts_sections, date, police_station, location_id, investigation_id, created_at) VALUES ('fir-107', 'FIR-107/2026', 'Incident Report: Hawala Cash Movement Pattern #7', 'Field intelligence report detailing regional syndicate incident #7 involving localized transport and digital remittance coercion.', 'IPC 384, 420, 120B / IT Act 66D', '2026-08-09T00:00:00+00:00', 'Gurugram Cyber PS', 'loc-l-08', 'inv-001', '2026-08-09T00:00:00+00:00') ON CONFLICT (id) DO NOTHING;
