INSERT INTO alerts (id, alert_code, alert_type, title, description, confidence, severity, status, investigation_id, entities, supporting_evidence_codes, explanation_factors, created_at) VALUES ('alt-017', 'NET-017', 'emerging_network', 'Emerging Multi-Modal Syndicate Convergence Detected', 'Cross-jurisdictional convergence identified between Fleet Extortion Cell (Comm-A), Port Logistics Cell (Comm-B), and Hawala Layering Hub (Comm-C). A sharp acceleration of multi-modal ties formed over the last 28 days centered around Person P-014.', 89.4, 'critical', 'new', 'inv-001', '[{"code": "P-014", "name": "Vikram Malhotra", "role": "Bridge / Coordinator"}, {"code": "P-021", "name": "Tariq Ahmed", "role": "Maritime Expeditor"}, {"code": "P-033", "name": "Kunal Verma", "role": "Crypto Escrow / Mule"}, {"code": "P-037", "name": "Aman Singhania", "role": "Bullion Banker"}, {"code": "V-009", "name": "DL-01-AX-9921", "role": "Shared Recon Vehicle"}, {"code": "L-012", "name": "Dockyard Warehouse 4B", "role": "Meeting Hub"}, {"code": "B-021", "name": "Swift Horizons ACC-992140", "role": "Clearing Hub"}]'::jsonb, '["FIR-102", "CDR-783", "TX-091", "VR-021", "SUR-009"]'::jsonb, '[{"factor": "Accelerated Communications", "detail": "4 new encrypted VoIP communication links established between P-014, P-021, and P-033."}, {"factor": "Shared Geolocation Cluster", "detail": "3 shared locations detected within a 72-hour window, specifically at Dockyard Warehouse 4B (L-012)."}, {"factor": "High-Velocity Capital Movement", "detail": "4 structured financial transfers totaling \u20b910,40,000 routed through shell account B-021."}, {"factor": "Shared Vehicle Reconnaissance", "detail": "Vehicle V-009 recorded at multiple disparate syndicate incident sites within 48 hours."}, {"factor": "Activity Acceleration Rate", "detail": "73% surge in interaction frequency compared to the 30-day baseline period."}, {"factor": "Multi-Community Bridging", "detail": "Direct bridge formed across 3 previously disconnected criminal network clusters."}]'::jsonb, '2026-09-02T00:00:00+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO alerts (id, alert_code, alert_type, title, description, confidence, severity, status, investigation_id, entities, supporting_evidence_codes, explanation_factors, created_at) VALUES ('alt-009', 'ACT-009', 'coordinated_activity', 'Coordinated Extortion & Diversion Incident Sequence', 'Multi-step sequential operational pattern detected across 4 participants, 2 locations, and 7 communication handoffs within a 72-hour window preceding the Dhaula Kuan incident.', 84.2, 'high', 'investigating', 'inv-001', '[{"code": "P-014", "name": "Vikram Malhotra"}, {"code": "P-011", "name": "Suresh Nair"}, {"code": "P-009", "name": "Devendra Yadav"}, {"code": "V-009", "name": "DL-01-AX-9921"}]'::jsonb, '["FIR-102", "CDR-783", "VR-021"]'::jsonb, '[{"factor": "Sequential Workflow", "detail": "Call from P-014 to P-011 -> Fund transfer from B-021 to B-008 -> Meeting at L-004 -> Incident FIR-102 at L-005."}, {"factor": "Tight Time Window", "detail": "All 5 operational steps transpired within 72 hours with sub-2 hour handoff intervals."}, {"factor": "Vehicle Corroboration", "detail": "V-009 observed departing L-004 exactly 45 minutes before the roadblock occurred."}]'::jsonb, '2026-08-29T00:00:00+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO alerts (id, alert_code, alert_type, title, description, confidence, severity, status, investigation_id, entities, supporting_evidence_codes, explanation_factors, created_at) VALUES ('alt-012', 'HID-012', 'hidden_relationship', 'Potential Indirect Connection: Vikram Malhotra (P-014) <-> Aman Singhania (P-037)', 'Graph link-prediction algorithms detected a strong latent relationship between P-014 and P-037 despite zero direct telecommunication records between their primary registered devices.', 87.1, 'high', 'new', 'inv-001', '[{"code": "P-014", "name": "Vikram Malhotra"}, {"code": "P-037", "name": "Aman Singhania"}]'::jsonb, '["TX-091", "FIN-033", "SUR-009"]'::jsonb, '[{"factor": "Common Associates (4 Mutual Neighbors)", "detail": "Both maintain dense, active edges with Tariq Ahmed (P-021), Kunal Verma (P-033), Suresh Nair (P-011), and Meera Sen (P-035)."}, {"factor": "Shared Physical Geolocation (3 Sites)", "detail": "Concurrent tower pings at Aerocity Hotel Zenith (L-018), CP Financial Arcade (L-003), and Dockyard Warehouse 4B (L-012)."}, {"factor": "Intermediary Financial Pass-Through", "detail": "Fund trail traces \u20b94,20,000 from P-014''s shell B-021 through Kunal Verma''s mule accounts into Aman Singhania''s bullion ledger B-037."}]'::jsonb, '2026-09-04T00:00:00+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO alerts (id, alert_code, alert_type, title, description, confidence, severity, status, investigation_id, entities, supporting_evidence_codes, explanation_factors, created_at) VALUES ('alt-015', 'FIN-015', 'financial_pattern', 'Potentially Suspicious Circular Wash Transfer Pattern', 'Cyclic fund movement detected: B-008 -> B-015 -> B-021 -> B-014 -> B-008 totaling ₹12,00,000 without identifiable underlying commercial goods exchange.', 91.2, 'critical', 'new', 'inv-001', '[{"code": "B-008", "name": "Axis Bank Extortion Pool"}, {"code": "B-015", "name": "Kotak Maritime Port Account"}, {"code": "B-021", "name": "Swift Horizons FinTech Hub"}, {"code": "B-014", "name": "Trident Global Logistics Operational"}]'::jsonb, '["TX-091", "TX-092", "TX-093", "TX-094"]'::jsonb, '[{"factor": "Closed Circular Loop", "detail": "Capital returns to initial originating syndicate account within 10 days after passing through 4 distinct corporate entities."}, {"factor": "Velocity Structuring", "detail": "Each leg executed within 48 hours of preceding credit to avoid regulatory freeze thresholds."}, {"factor": "Synthetic Invoicing", "detail": "Invoices cited non-existent maritime container clearance and consultancy fees."}]'::jsonb, '2026-08-31T00:00:00+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO osint_results (id, investigation_id, query, title, snippet, url, source_domain, published_at, retrieved_at, relevance_score, entities_found, verification_status, created_at) VALUES ('osint-001', 'inv-001', 'Trident Global Logistics Vikram Malhotra JNPT port expansion', 'Trident Global Logistics Announces Major Coastal Warehousing Expansion at Nhava Sheva', 'Logistics daily reports that Trident Global Logistics, headed by Managing Director Vikram Malhotra, has leased over 45,000 sq ft at Dockyard Terminal 4B. The company recently raised substantial private debt for multi-modal fleet acquisitions...', 'https://industry-press.example.com/logistics/2026/08/trident-global-nhava-expansion', 'industry-press.example.com', '2026-08-15T00:00:00+00:00', '2026-09-05T00:00:00+00:00', 94.0, '["Vikram Malhotra", "Trident Global Logistics", "Dockyard Warehouse 4B", "Nhava Sheva"]'::jsonb, 'unverified', '2026-09-05T00:00:00+00:00') ON CONFLICT (id) DO NOTHING;
